package org.dromara.property.charge.rule.service.impl;
import com.baomidou.mybatisplus.core.MybatisConfiguration; import com.baomidou.mybatisplus.core.metadata.TableInfoHelper; import org.apache.ibatis.builder.MapperBuilderAssistant; import org.dromara.common.core.exception.ServiceException; import org.dromara.property.charge.item.domain.ChargeItem; import org.dromara.property.charge.item.mapper.ChargeItemMapper; import org.dromara.property.charge.rule.domain.ChargeRule; import org.dromara.property.charge.rule.domain.bo.ChargeRuleBo; import org.dromara.property.charge.rule.mapper.ChargeRuleMapper; import org.dromara.property.project.mapper.ProjectMapper; import org.dromara.property.scope.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.math.BigDecimal; import java.time.LocalDate; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class ChargeRuleServiceSecurityTest {
 @Mock ChargeRuleMapper mapper; @Mock ChargeItemMapper itemMapper; @Mock ProjectMapper projectMapper; @Mock PropertyProjectScopeService scope; ChargeRuleServiceImpl service;
 @BeforeEach void init(){TableInfoHelper.initTableInfo(new MapperBuilderAssistant(new MybatisConfiguration(),"rule"),ChargeRule.class);service=new ChargeRuleServiceImpl(mapper,itemMapper,projectMapper,scope);}
 @Test void detailUsesPersistedProject(){when(mapper.selectById(9L)).thenReturn(rule(9L,101L));doThrow(new ServiceException("deny")).when(scope).assertBusinessAccess(101L,PropertyBusinessDomain.FINANCE,ProjectBusinessAction.READ);assertThrows(ServiceException.class,()->service.queryById(9L));verify(mapper,never()).selectVoById(9L);}
 @Test void updateRejectsCrossProjectAndCodeMutation(){when(mapper.selectActiveByIdForUpdate(9L)).thenReturn(rule(9L,101L));ChargeRuleBo b=valid();b.setId(9L);b.setProjectId(202L);assertEquals("所属项目不允许修改",assertThrows(ServiceException.class,()->service.update(b)).getMessage());b.setProjectId(101L);b.setRuleCode("OTHER");assertEquals("规则编码不允许修改",assertThrows(ServiceException.class,()->service.update(b)).getMessage());}
 @Test void rejectsCrossProjectAndNonPeriodicItem(){ChargeRuleBo b=valid();b.setProjectId(101L);ChargeItem item=new ChargeItem();item.setId(3L);item.setProjectId(202L);item.setStatus("0");item.setChargeType("PERIODIC");when(itemMapper.selectById(3L)).thenReturn(item);assertTrue(assertThrows(ServiceException.class,()->service.update(withCurrent(b))).getMessage().contains("不属于"));item.setProjectId(101L);item.setChargeType("METER");assertTrue(assertThrows(ServiceException.class,()->service.update(withCurrent(b))).getMessage().contains("周期性"));}
 @Test void validatesAmountConsistency(){when(mapper.selectActiveByIdForUpdate(9L)).thenReturn(rule(9L,101L));ChargeItem i=new ChargeItem();i.setId(3L);i.setProjectId(101L);i.setStatus("0");i.setChargeType("PERIODIC");when(itemMapper.selectById(3L)).thenReturn(i);ChargeRuleBo b=valid();b.setId(9L);b.setProjectId(101L);b.setFixedAmount(BigDecimal.ONE);assertTrue(assertThrows(ServiceException.class,()->service.update(b)).getMessage().contains("固定金额必须为空"));}
 private ChargeRuleBo withCurrent(ChargeRuleBo b){b.setId(9L);when(mapper.selectActiveByIdForUpdate(9L)).thenReturn(rule(9L,101L));return b;} private static ChargeRuleBo valid(){ChargeRuleBo b=new ChargeRuleBo();b.setChargeItemId(3L);b.setRuleCode("RULE");b.setRuleName("物业费");b.setBillingMethod("AREA");b.setBillingCycle("MONTH");b.setCycleMode("NATURAL");b.setUnitPrice(BigDecimal.ONE);b.setEffectiveStartDate(LocalDate.now());b.setStatus("0");return b;} private static ChargeRule rule(long id,long pid){ChargeRule r=new ChargeRule();r.setId(id);r.setProjectId(pid);r.setRuleCode("RULE");return r;}
}
